export const getCreateDeploymentUrl = (environmentId: string,) => {




  return `/api/v1/environments/${environmentId}/deployments`
}

/**
 * Protected environments need an allowed role; those that require approvals only take
 * pipeline deploys (`ENVIRONMENT_PROTECTED`, `details.reason` = role | approvals). One
 * deployment at a time per environment (`DEPLOYMENT_IN_PROGRESS`). Blue/green is for
 * Kubernetes targets with a service (`STRATEGY_NOT_SUPPORTED`).
 * @summary Deploy an image to the environment (deployment.create)
 */
export const createDeployment = async (environmentId: string,
    createDeploymentRequest: CreateDeploymentRequest, options?: Parameters<typeof customFetch>[1]): Promise<Deployment> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Deployment>(getCreateDeploymentUrl(environmentId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(createDeploymentRequest)
  }
);}





